import { writeFileSync, mkdirSync } from 'node:fs';

// Category: merge-keys
//
// The "<<" merge key. Covers: merging a single mapping, merging a list of
// mappings (order matters), merge plus locally-overridden keys, nested merges
// (a merge source that itself contains a merge), merges inside flow mappings,
// merges at every position in a mapping, aliases pointing at mappings used as
// merge sources, and invalid merge values.
//
// Reference semantics worth pinning down (PyYAML flatten_mapping):
//   * merged pairs are prepended: node.value = merge + node.value, so merged
//     keys occupy earlier insertion slots than local keys no matter where the
//     "<<" entry physically sits.
//   * for "<<: [A, B, C]" the submerge list is REVERSED before extending, so
//     insertion order is C, B, A -- yet A wins a key conflict because its pair
//     is assigned last into the dict (re-assignment keeps the original slot).
//   * a local key always beats every merge source.
//   * merge sources are flattened recursively, so nested "<<" works.
// Insertion order is normally invisible because yaml.dump sorts keys, so many
// ordering cases below deliberately mix int and str keys: sorted() then raises
// TypeError, PyYAML swallows it, and the raw insertion order is emitted.
//
// NOTE: the single case whose text starts with "-" keeps a space on its first
// line so argparse treats it as a value rather than an option flag.

const OUT_DIR = '/workspace/probe/corpus/merge-keys';

const cases = [
