// keep the corpus honest: every case must be unique
const seen = new Set();
for (const c of cases) {
  if (seen.has(c)) throw new Error('duplicate case: ' + JSON.stringify(c));
  seen.add(c);
}

mkdirSync(OUT_DIR, { recursive: true });
cases.forEach((text, i) => {
  const name = String(i + 1).padStart(3, '0') + '.txt';
  writeFileSync(OUT_DIR + '/' + name, text);
});
console.log('merge-keys: wrote ' + cases.length + ' cases to ' + OUT_DIR);
